let tasks=JSON.parse(localStorage.getItem('mam-tasks')||'[]');
const input=document.querySelector('.new-todo'),list=document.querySelector('.todo-list');
function render(){
 localStorage.setItem('mam-tasks',JSON.stringify(tasks));list.replaceChildren();
 tasks.forEach((x,i)=>{
  if(location.hash.includes('active')&&x.done)return;
  if(location.hash.includes('completed')&&!x.done)return;
  const row=document.createElement('li');row.dataset.testid='todo-item';
