  const del=document.createElement('button');del.className='destroy';del.ariaLabel='Delete';
  del.textContent='×';del.onclick=()=>{tasks.splice(i,1);render();};
  row.append(box,label,del);list.append(row);
 });
 const n=tasks.filter(x=>!x.done).length;
 document.querySelector('[data-testid=todo-count]').textContent=n+(n===1?' item left':' items left');
 document.querySelector('.clear-completed').hidden=!tasks.some(x=>x.done);
}
input.onkeydown=e=>{if(e.key==='Enter'&&input.value.trim()){
