def browser_page(path,query):
 if path.startswith('/todomvc'):return TODO
 if path=='/login':return """<h2>Lab Login</h2><form action=/authenticate>
 <label for=username>Tên lab</label><input id=username name=username>
 <label for=password>Chuỗi lab</label><input type=password id=password name=password>
 <button type=submit>Vào lab</button></form><div id=flash></div>"""
 if path=='/authenticate':
  ok=query.get('username')==['lab-student'] and query.get('password')==['LAB_ONLY_NOT_SECRET']
  text='Lab login accepted' if ok else 'Lab secret rejected'
  return f'<h2>Lab result</h2><div id=flash class={"success" if ok else "error"}>{text}</div>'
 if path=='/checkboxes':return '<h3>Lab checkboxes</h3><form id=checkboxes><input type=checkbox><input type=checkbox checked></form>'
 if path.startswith('/dynamic_loading/'):
  hidden=path.endswith('/1')
  existing='<div id=finish hidden>Hello lab!</div>' if hidden else ''
  script="document.getElementById('finish').hidden=false" if hidden else "document.body.insertAdjacentHTML('beforeend','<div id=finish>Hello lab!</div>')"
  return '<div id=start><button onclick="setTimeout(()=>{'+script+'},700)">Start</button></div>'+existing
 if path=='/dynamic_controls':return """<div id=checkbox><input type=checkbox></div>
 <button onclick="setTimeout(()=>{document.getElementById('checkbox').remove();document.getElementById('message').textContent='Removed in lab';},600)">Remove</button><p id=message></p>"""
 if path=='/dropdown':return '<h3>Lab select</h3><select id=dropdown><option value="">Choose</option><option value=1>Option 1</option><option value=2>Option 2</option></select>'
 if path=='/javascript_alerts':return """<h3>Lab dialogs</h3>
 <button onclick="alert('Lab alert');document.getElementById('result').textContent='Lab alert accepted'">Click for JS Alert</button>
 <button onclick="document.getElementById('result').textContent=confirm('Lab confirm')?'OK':'Cancelled'">Click for JS Confirm</button>
 <button onclick="document.getElementById('result').textContent='Lab input: '+prompt('Lab prompt')">Click for JS Prompt</button><p id=result></p>"""
 if path=='/iframe':return '<h3>Lab frame</h3><iframe id=mce_0_ifr title="Lab editor" src=/frame></iframe>'
 if path=='/frame':return '<body id=tinymce contenteditable=true>Lab editable text.</body>'
 if path=='/windows':return '<h3>Lab windows</h3><a href=/windows/new target=_blank>Click Here</a>'
 if path=='/windows/new':return '<h3>Lab New Window</h3>'
 if path=='/secure':return '<h3>Lab secure placeholder</h3>'
 return '<h1>UI fixture Mầm</h1><a href=/login>Login</a><a href=/todomvc>Todo</a>'
class LabUI(BaseHTTPRequestHandler):
 def log_message(self,*args):pass
 def do_GET(self):
  url=urlsplit(self.path);body=browser_page(url.path,parse_qs(url.query))
  raw=('<!doctype html><html lang=vi><meta charset=utf-8><title>UI Lab Mầm</title>'+body).encode('utf-8') if not body.startswith('<!doctype') else body.encode('utf-8')
  self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8')
  self.send_header('Content-Length',str(len(raw)));self.end_headers();self.wfile.write(raw)
if __name__=='__main__':
 print('UI fixture http://localhost:3131 ; Ctrl+C để dừng')
 ThreadingHTTPServer(('localhost',3131),LabUI).serve_forever()

