from collections import deque
def shortest_path(graph,start,goal):
    if start not in graph or goal not in graph:return None
    parent={start:None};q=deque([start])
    while q:
        u=q.popleft()
        if u==goal:
            path=[]
            while u is not None:path.append(u);u=parent[u]
            return path[::-1]
        for v in graph[u]:
            if v not in graph:raise ValueError("unknown_node")
            if v not in parent:parent[v]=u;q.append(v)
    return None

def valid_path(graph,path,start,goal):
    if not path or path[0]!=start or path[-1]!=goal:return False
    return all(v in graph[u] for u,v in zip(path,path[1:]))
assert valid_path(world,["Cổng Mầm","Sân Thoi","Tháp Nếp"],"Cổng Mầm","Tháp Nếp")
